def is_valid(isbn):
    cleaned_isbn = isbn.replace('-', '')

    if len(cleaned_isbn) != 10:
        return False

    digits_value = []
    for i, char in enumerate(cleaned_isbn):
        if i < 9:
            # First 9 characters must be digits
            if not char.isdigit():
                return False
            digits_value.append(int(char))
        else:
            # The 10th character (check digit) can be a digit or 'X'
            if char.isdigit():
                digits_value.append(int(char))
            elif char == 'X':
                digits_value.append(10)
            else:
                return False # Invalid character for the check digit

    # Calculate the sum using the ISBN-10 formula
    total_sum = 0
    multiplier = 10
    for digit in digits_value:
        total_sum += digit * multiplier
        multiplier -= 1

    # Check if the sum is a multiple of 11
    return total_sum % 11 == 0
